ceny = {"čaj": "35", "káva": "chyba", "voda": "25"}
celkem = 0
# Každou položku zpracujeme zvlášť, chyba nezastaví ostatní.
for nazev, text in ceny.items():
    try:
        celkem += int(text)
    except ValueError:
        print("Neplatná cena:", nazev)
# Součet obsahuje jen úspěšné převody.
print("Součet platných cen:", celkem)

def najdi(kontakty, jmeno):
    # Přímý přístup může vyvolat KeyError.
    try:
        return kontakty[jmeno]
    except KeyError:
        return "Kontakt chybí"


kontakty = {"Ema": "111 222 333"}
print(najdi(kontakty, "Ema"))
# Zachycení konkrétní výjimky nezakrývá jiné chyby.
print(najdi(kontakty, "Jan"))
